ALTER TABLE wound_case ADD COLUMN source_linked INTEGER NOT NULL DEFAULT 0 CHECK(source_linked IN (0,1));
ALTER TABLE wound_case ADD COLUMN enemy_action TEXT NOT NULL DEFAULT 'unknown' CHECK(enemy_action IN ('yes','no','unknown'));
ALTER TABLE wound_case ADD COLUMN source_recorded_at TEXT;
ALTER TABLE wound_case ADD COLUMN patient_received_at TEXT;
ALTER TABLE wound_case ADD COLUMN continuous_start TEXT;
ALTER TABLE wound_case ADD COLUMN care_applicability TEXT NOT NULL DEFAULT 'unknown';
ALTER TABLE wound_case ADD COLUMN current_episode TEXT;
ALTER TABLE wound_case ADD COLUMN freshness_state TEXT NOT NULL DEFAULT 'unknown';
ALTER TABLE wound_case ADD COLUMN last_source_at TEXT;
ALTER TABLE case_event ADD COLUMN minimal_payload TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(minimal_payload));
ALTER TABLE document_ref ADD COLUMN state TEXT NOT NULL DEFAULT 'referenced';
ALTER TABLE document_ref ADD COLUMN active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1));
ALTER TABLE financial_track ADD COLUMN packet_ref TEXT;
ALTER TABLE financial_track ADD COLUMN source_system TEXT;
ALTER TABLE financial_track ADD COLUMN decision_at TEXT;
CREATE TABLE source_cursor(source TEXT NOT NULL,stream TEXT NOT NULL,event_type TEXT NOT NULL,version TEXT NOT NULL,PRIMARY KEY(source,stream,event_type)) STRICT;
CREATE TABLE incident_link(source TEXT NOT NULL,subject_id TEXT NOT NULL REFERENCES subject(id),incident_ref TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES wound_case(id),proof TEXT NOT NULL,PRIMARY KEY(source,subject_id,incident_ref)) STRICT;
CREATE TABLE demo_command(id TEXT PRIMARY KEY,actor TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES wound_case(id),digest TEXT NOT NULL,outcome TEXT NOT NULL CHECK(json_valid(outcome))) STRICT;
CREATE TABLE route_packet(case_id TEXT NOT NULL REFERENCES wound_case(id),route TEXT NOT NULL,packet_ref TEXT NOT NULL,revision TEXT NOT NULL,received_at TEXT,reason TEXT,state TEXT NOT NULL,period TEXT,PRIMARY KEY(case_id,route,packet_ref)) STRICT;
CREATE TABLE analytics_snapshot(id TEXT PRIMARY KEY,payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TRIGGER snapshot_no_update BEFORE UPDATE ON analytics_snapshot BEGIN SELECT RAISE(ABORT,'immutable_snapshot'); END;
CREATE TRIGGER snapshot_no_delete BEFORE DELETE ON analytics_snapshot BEGIN SELECT RAISE(ABORT,'immutable_snapshot'); END;
CREATE TABLE demo_setting(id TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
